// Magma fixtures for quaternion algebras over real quadratic fields
// (engine/hmf/src/quatalg.rs; tests only): Magma is used as a black box.
// Run from this directory with
//     magma -b magma-quat.m > magma-quat.txt
// For each line d | a b | den | h of quat-orders.txt (our algebra
// (a, b)_F over F = Q(sqrt d) and our maximal order, the span over Z of
// the rows of h / den in the Q-basis e_m, w e_m with e = 1, i, j, k and w
// as in rqf.rs), a line
//     d | r | m | u | n | n1
// with r the number of finite ramified places of (a, b)_F, m whether the
// order generated by our basis is maximal, u whether its discriminant is
// (1), n the order of UnitGroup (O^x / O_F^x) and n1 = 2 #{units modulo
// O_F^x whose reduced norm is a square in F} = #{x in O : nrd(x) = 1}
// (u has nrd(u eps) = 1 for a unit eps exactly when nrd(u) = eps^-2).
SetColumns(0);
R<x> := PolynomialRing(Rationals());
va, vb, vc := GetVersion();
printf "# Magma %o.%o-%o, black box: QuaternionAlgebra, RamifiedPlaces, Order, IsMaximal, Discriminant, UnitGroup\n", va, vb, vc;
// the integers in a string (Split keeps an empty leading field)
ints := func<s | [eval t : t in Split(s, " ") | #t gt 0]>;
lines := [l : l in Split(Read("quat-orders.txt"), "\n") | #l gt 0 and l[1] ne "#"];
for l in lines do
  p := Split(l, "|");
  d := ints(p[1])[1];
  ab := ints(p[2]);
  den := ints(p[3])[1];
  h := ints(p[4]);
  if d mod 4 eq 1 then
    F<w> := NumberField(x^2 - x - (d - 1) div 4);
  else
    F<w> := NumberField(x^2 - d);
  end if;
  ZF := Integers(F);
  A<i, j, k> := QuaternionAlgebra<F | ab[1], ab[2]>;
  e := [A!1, i, j, k];
  basis := [&+[(h[8*r + 2*m + 1] + h[8*r + 2*m + 2]*w) / den * e[m + 1] : m in [0..3]] : r in [0..7]];
  O := Order(basis);
  assert &and[x in O : x in basis];
  fin, inf := RamifiedPlaces(A);
  assert #inf eq 2;
  U, mu := UnitGroup(O);
  n1 := 2 * #[g : g in U | IsSquare(F!Norm(mu(g)))];
  printf "%o | %o | %o | %o | %o | %o\n", d, #fin, IsMaximal(O), Discriminant(O) eq ideal<ZF | 1>, #U, n1;
end for;
quit;
